import math
def p1(face,cpn,y,n): return sum(face*cpn/(1+y)**k for k in range(1,n+1))+face/(1+y)**n
def dur(face,cpn,y,n):
    P=p1(face,cpn,y,n); h=1e-4
    return -(p1(face,cpn,y+h,n)-p1(face,cpn,y-h,n))/(2*h*P)
def run(c):
    for k,v in zip(range(1,5),(38.10,36.28,34.55,32.91)): c(f'VA coupon {k}', 40/1.05**k, v, 0.005)
    c('VA final', 1040/1.05**5, 814.87, 0.005); c('prix 5y 5%', p1(1000,.04,.05,5), 956.71, 0.005); c('prix 5y 4%', p1(1000,.04,.04,5), 1000.0, 1e-6); c('prix 5y 3%', p1(1000,.04,.03,5), 1045.80, 0.005)
    for y,(a,b,d) in {.03:(1045.80,1085.30,1196.00),.05:(956.71,922.78,846.28),.06:(915.75,852.80,724.70)}.items():
        c(f'5y {y}', p1(1000,.04,y,5), a, 0.005); c(f'10y {y}', p1(1000,.04,y,10), b, 0.005); c(f'30y {y}', p1(1000,.04,y,30), d, 0.005)
    c('-5y', (p1(1000,.04,.05,5)/1000-1)*100, -4.33, 0.005); c('-10y', (p1(1000,.04,.05,10)/1000-1)*100, -7.72, 0.005); c('-30y', (p1(1000,.04,.05,30)/1000-1)*100, -15.37, 0.005)
    c('+30y', (p1(1000,.04,.03,30)/1000-1)*100, 19.60, 0.005)
    c('zéro 10y 4%', 1000/1.04**10, 675.56, 0.005); c('zéro 10y 5%', 1000/1.05**10, 613.91, 0.005); c('zéro var', (1000/1.05**10/(1000/1.04**10)-1)*100, -9.13, 0.005)
    def sec(y): 
        i=y/2; return sum(15/(1+i)**k for k in range(1,19))+1000/(1+i)**18
    c('SEC 2%', sec(0.02), 1081.99, 0.005); c('SEC 4%', sec(0.04), 925.04, 0.005); c('SEC arrondi 2%', round(sec(0.02)), 1082); c('SEC arrondi 4%', round(sec(0.04)), 925)
    c('durée 5y', dur(1000,.04,.04,5), 4.45, 0.005); c('durée 10y', dur(1000,.04,.04,10), 8.11, 0.005); c('durée 30y', dur(1000,.04,.04,30), 17.29, 0.005)
    c('rendement actuel', 40/956.71*100, 4.18, 0.005); c('gain capital', 1000-956.71, 43.29, 0.005); c('rend actuel prime', 40/1045.80*100, 3.82, 0.005)
    c('pente 10-2', 4.44-4.14, 0.30, 1e-9); c('pente 10-3m', 4.44-3.87, 0.57, 1e-9); c('pente 5-3m', 4.19-3.87, 0.32, 1e-9); c('6m-1a', 3.98-4.01, -0.03, 1e-9); c('30a-20a', 4.91-4.93, -0.02, 1e-9)
    c('Ex1a', p1(1000,.05,.04,3), 1027.75, 0.01); c('Ex1b', p1(1000,.05,.05,3), 1000.0, 1e-6); c('Ex1c', p1(1000,.05,.06,3), 973.27, 0.005)
    c('Ex2a', 1000/1.03**5, 862.61, 0.005); c('Ex2b', 1000/1.04**5, 821.93, 0.005); c('Ex2c', (1000/1.04**5/(1000/1.03**5)-1)*100, -4.72, 0.005)
    c('Ex2d prix', 1000/1.05**5, 783.53, 0.005); c('Ex2d var', (1000/1.05**5/(1000/1.04**5)-1)*100, -4.67, 0.005)
    c('Ex3 annuité 1%', (1-1.01**-18)/0.01, 16.398, 0.001); c('Ex3 VA nominal 1%', 1000/1.01**18, 836.0, 0.05); c('Ex3 annuité 2%', (1-1.02**-18)/0.02, 14.992, 0.001); c('Ex3 VA nominal 2%', 1000/1.02**18, 700.16, 0.005)
    c('Q2', p1(1000,.04,.05,5), 956.71, 0.005); c('Q6', 40/956.71*100, 4.18, 0.005); c('Q7', 4.44-3.87, 0.57, 1e-9)
